                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db_wooqer AS ( WITH preprocessed_data AS ( SELECT a.*, a.\"coverage-name\" AS Store, a.\"DATE\" AS \"Date (dd/mm/yyyy)\", TO_DATE(a.\"DATE\", \'YYYY-MM-DD\') AS process_date, EXTRACT(WEEK FROM TO_DATE(a.\"DATE\", \'YYYY-MM-DD\')) AS week_number, CASE WHEN a.\"coverage-name\" = \'NEW BEL ROAD BANGALORE\' THEN \'SNITCH - COCO - BEL ROAD\' WHEN a.\"coverage-name\" = \'BHARTIYA CITY\' THEN \'SNITCH - COCO - BHARTIYA CITY\' WHEN a.\"coverage-name\" = \'ESPLANADE MALL\' THEN \'SNITCH - COCO - ESPLANADE MALL\' WHEN a.\"coverage-name\" = \'HILITE\' THEN \'SNITCH - COCO - HILITE\' WHEN a.\"coverage-name\" = \'HSR LAYOUT BANGALORE\' THEN \'SNITCH - COCO - HSR LAYOUT\' WHEN a.\"coverage-name\" = \'JAYANAGAR BANGALORE\' THEN \'SNITCH - COCO - JAYANAGAR\' WHEN a.\"coverage-name\" = \'MantriAvenue\' THEN \'SNITCH - COCO - KORMANGLA\' WHEN a.\"coverage-name\" = \'Lulu Mall\' THEN \'SNITCH - COCO - LULU MALL\' WHEN a.\"coverage-name\" = \'AMANORA\' THEN \'SNITCH - COFO - AMANORA\' WHEN a.\"coverage-name\" = \'BANER PUNE\' THEN \'SNITCH - COFO - BANER\' WHEN a.\"coverage-name\" = \'BRIGADE ROAD BANGALORE\' THEN \'SNITCH - COFO - BRIGADE ROAD\' WHEN a.\"coverage-name\" = \'CITY CENTER\' THEN \'SNITCH - COFO - CC MANGALORE\' WHEN a.\"coverage-name\" = \'INFINITI ANDHERI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN a.\"coverage-name\" = \'INFINITI MALAD\' THEN \'SNITCH - COFO - INFINITI MALAD\' WHEN a.\"coverage-name\" = \'INFINITY VASHI\' THEN \'SNITCH - COFO - INORBIT VASHI\' WHEN a.\"coverage-name\" = \'KUKATPALLY\' THEN \'SNITCH - COFO - KUKATPALLY\' WHEN a.\"coverage-name\" = \'BANDRA\' THEN \'SNITCH - COFO - LINKING ROAD\' WHEN a.\"coverage-name\" = \'Kalyan Metro\' THEN \'SNITCH - COFO - METRO MALL\' WHEN a.\"coverage-name\" = \'RAJPUR ROAD DEHRADUN\' THEN \'SNITCH - COFO - RAJPURA ROAD\' WHEN a.\"coverage-name\" = \'SARATH CITY\' THEN \'SNITCH - COFO - SARATH CITY\' WHEN a.\"coverage-name\" = \'TRIBECA\' THEN \'SNITCH - COFO - TRIBECA\' WHEN a.\"coverage-name\" = \'VIP ROAD VIZAG\' THEN \'SNITCH - COFO - VIZAG\' WHEN a.\"coverage-name\" = \'C ROAD JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN a.\"coverage-name\" = \'DB MALL BHOPAL\' THEN \'SNITCH - FOCO - DB MALL\' WHEN a.\"coverage-name\" = \'PMC CITADEL\' THEN \'SNITCH - FOCO - PHEONIX CITADEL\' WHEN a.\"coverage-name\" = \'SHYAMAL\' THEN \'SNITCH - FOCO - SHYAMAL\' WHEN a.\"coverage-name\" = \'TRION VADODARA\' THEN \'SNITCH - FOCO - TRION\' WHEN a.\"coverage-name\" = \'VAISHALI NAGAR JAIPUR\' THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN a.\"coverage-name\" = \'VR MALL SURAT\' THEN \'SNITCH - FOCO - VR MALL\' WHEN a.\"coverage-name\" = \'YAGNIK\' THEN \'SNITCH - FOCO - YAGNIK\' WHEN a.\"coverage-name\" = \'EARTH EUPHORIA\' THEN \'SNITCH - FOCO - EARTH EUPHORIA\' WHEN a.\"coverage-name\" = \'EVA VADODARA\' THEN \'SNITCH - FOCO - EVA\' WHEN a.\"coverage-name\" = \'LANDMARK GANDHI NAGAR\' THEN \'SNITCH - FOCO - GANDHI NAGAR\' WHEN a.\"coverage-name\" = \'MBH VARACHHA SURAT\' THEN \'SNITCH - FOCO - MBH\' WHEN a.\"coverage-name\" = \'Express Avenue\' THEN \'SNITCH - COFO - EXPRESS AVENUE\' WHEN a.\"coverage-name\" = \'Elpro City Square Mall\' THEN \'SNITCH - COFO - ELPRO MALL\' WHEN a.\"coverage-name\" = \'Phoenix Mall BLR\' THEN \'SNITCH - COCO - PMC WHITEFIELD MALL\' WHEN a.\"coverage-name\" = \'Orion Avenue\' THEN \'SNITCH - COCO - ORION MALL AVENUE\' WHEN a.\"coverage-name\" = \'Bansankari\' THEN \'SNITCH - COCO - BANASHANKARI\' WHEN a.\"coverage-name\" = \'City Center, Guwahati\' THEN \'SNITCH - COCO - GUWAHATI\' WHEN a.\"coverage-name\" = \'Kothapet\' THEN \'SNITCH - COFO - KOTHAPET\' WHEN a.\"coverage-name\" = \'Lajpat Nagar\' THEN \'SNITCH - COCO - LAJPAT NAGAR\' WHEN a.\"coverage-name\" = \'Phoenix Palassio\' THEN \'SNITCH - FOCO - PALASSIO MALL\' WHEN a.\"coverage-name\" = \'Rajahmundry\' THEN \'SNITCH - COFO - RAJAHMUNDRY\' WHEN a.\"coverage-name\" = \'Hubli\' THEN \'SNITCH - COFO - HUBLI\' ELSE \'Unknown Store\' END AS store_name_mapping, CASE a.\"EVID\" WHEN \'106883\' THEN \'Opening Checklist\' WHEN \'107233\' THEN \'Closing Checklist\' WHEN \'108750\' THEN \'Grooming-1st Shift\' WHEN \'111803\' THEN \'VM Thursday\' WHEN \'115439\' THEN \'VM Daily Checklist\' WHEN \'115445\' THEN \'Inventory Daily Checklist\' WHEN \'115923\' THEN \'Replenishment (3:00-4:00)\' WHEN \'115929\' THEN \'Replenishment (12:00-1:00)\' WHEN \'115930\' THEN \'Replenishment (6:00-7:00)\' WHEN \'116008\' THEN \'Replenishment (9:00-10:00)\' WHEN \'116009\' THEN \'Cash Deposit\' WHEN \'116067\' THEN \'Feedback Checklist\' END AS process, CASE WHEN a.\"SCORE\" = 0 THEN 1 ELSE a.\"SCORE\" END::NUMERIC AS \"Total Obtained Score\", CASE WHEN a.\"points-available\" = 0 THEN 1 ELSE a.\"points-available\" END::NUMERIC AS \"Total Available Score\" FROM export_report_2_export_report a ), active_processes AS ( SELECT DISTINCT process FROM preprocessed_data ), feedback_data AS ( SELECT a.\"coverage-name\", TO_DATE(a.\"DATE\", \'YYYY-MM-DD\') AS process_date, w.value:\"answer\"::STRING AS store_feedback FROM export_report_2_export_report a, LATERAL FLATTEN(input => a.\"WOOQLETS\") w WHERE a.\"EVID\" = \'116067\' AND REGEXP_COUNT(TRIM(w.value:\"answer\"::STRING), \'\\s+\') > 0 AND NOT REGEXP_LIKE(w.value:\"answer\"::STRING, \'^\d+$\') ), store_count AS ( SELECT process_date, COUNT(DISTINCT store_name_mapping) AS total_stores FROM preprocessed_data GROUP BY process_date ), process_classification AS ( SELECT subquery.process, CASE WHEN MAX(subquery.count_per_store_week) > 1 THEN \'Daily\' ELSE \'Weekly\' END AS process_type FROM ( SELECT pd.process, pd.store, pd.week_number, COUNT(*) AS count_per_store_week FROM preprocessed_data pd GROUP BY pd.process, pd.store, pd.week_number ) subquery GROUP BY subquery.process ), process_count AS ( SELECT pd.store_name_mapping AS store, pd.process_date, COUNT(DISTINCT CASE WHEN pc.process_type = \'Daily\' THEN pd.process END) AS daily_processes_completed, COUNT(DISTINCT CASE WHEN pc.process_type = \'Weekly\' THEN pd.process END) AS weekly_processes_completed FROM preprocessed_data pd JOIN process_classification pc ON pd.process = pc.process JOIN active_processes ap ON pd.process = ap.process GROUP BY pd.store_name_mapping, pd.process_date ), total_processes AS ( SELECT p.process_date, COUNT(DISTINCT CASE WHEN pc.process_type = \'Daily\' AND p.process_date BETWEEN p.process_date - INTERVAL \'3 DAYS\' AND p.process_date THEN p.process END) AS total_distinct_daily_processes, (SELECT COUNT(DISTINCT process) FROM process_classification WHERE process_type = \'Weekly\') AS total_distinct_weekly_processes FROM preprocessed_data p JOIN process_classification pc ON p.process = pc.process JOIN active_processes ap ON p.process = ap.process GROUP BY p.process_date ), replenishment_extracted AS ( SELECT a.\"coverage-name\" AS store, a.\"DATE\" AS process_date, a.\"EVID\", w.value:\"question\"::STRING AS question, TRY_CAST(w.value:\"answer\"::STRING AS INT) AS answer FROM export_report_2_export_report a, LATERAL FLATTEN(input => a.\"WOOQLETS\") w WHERE a.\"EVID\" IN (\'115923\', \'115929\', \'115930\', \'116008\') ), pivoted_replenishment AS ( SELECT DISTINCT re.store, re.process_date, re.\"EVID\", MAX(CASE WHEN re.question = \'Quantity Sold\' THEN re.answer END) AS quantity_sold, MAX(CASE WHEN re.question = \'Quantity Replenished\' THEN re.answer END) AS quantity_replenished, MAX(CASE WHEN re.question = \'Quantity Not Available in Store\' THEN re.answer END) AS quantity_not_available FROM replenishment_extracted re GROUP BY re.store, re.process_date, re.\"EVID\" ) SELECT pd.*, fd.store_feedback, CASE WHEN ap.process IS NOT NULL THEN 1 ELSE 0 END AS ACTIVE_PROCESS_FLAG, c.AM, c.RM, c.CITY, c.state, c.REGION, c.partner, c.\"BRANCH CODE\", am_count.AM_store_count, rm_count.RM_store_count, sc.total_stores, CASE WHEN pd.process IN (\'Replenishment (3:00-4:00)\', \'Replenishment (12:00-1:00)\', \'Replenishment (6:00-7:00)\', \'Replenishment (9:00-10:00)\') THEN pr.quantity_sold ELSE NULL END AS quantity_sold, CASE WHEN pd.process IN (\'Replenishment (3:00-4:00)\', \'Replenishment (12:00-1:00)\', \'Replenishment (6:00-7:00)\', \'Replenishment (9:00-10:00)\') THEN pr.quantity_replenished ELSE NULL END AS quantity_replenished, CASE WHEN pd.process IN (\'Replenishment (3:00-4:00)\', \'Replenishment (12:00-1:00)\', \'Replenishment (6:00-7:00)\', \'Replenishment (9:00-10:00)\') THEN pr.quantity_not_available ELSE NULL END AS quantity_not_available, pc.daily_processes_completed, pc.weekly_processes_completed, tp.total_distinct_daily_processes, tp.total_distinct_weekly_processes FROM preprocessed_data pd LEFT JOIN feedback_data fd ON pd.\"coverage-name\" = fd.\"coverage-name\" AND pd.process_date = fd.process_date LEFT JOIN store_count sc ON pd.process_date = sc.process_date LEFT JOIN process_count pc ON pd.store_name_mapping = pc.store AND pd.process_date = pc.process_date LEFT JOIN total_processes tp ON pd.process_date = tp.process_date LEFT JOIN active_processes ap ON pd.process = ap.process LEFT JOIN pivoted_replenishment pr ON pd.store = pr.store AND pd.process_date = pr.process_date AND pd.process = CASE WHEN pr.\"EVID\" = \'115923\' THEN \'Replenishment (3:00-4:00)\' WHEN pr.\"EVID\" = \'115929\' THEN \'Replenishment (12:00-1:00)\' WHEN pr.\"EVID\" = \'115930\' THEN \'Replenishment (6:00-7:00)\' WHEN pr.\"EVID\" = \'116008\' THEN \'Replenishment (9:00-10:00)\' END LEFT JOIN snitch_db.maplemonk.master_offine c ON TRIM(LOWER(pd.store_name_mapping)) = TRIM(LOWER(c.\"FROM BRANCH NAME\")) LEFT JOIN ( SELECT AM, COUNT(DISTINCT \"FROM BRANCH NAME\") AS AM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY AM ) am_count ON c.AM = am_count.AM LEFT JOIN ( SELECT \"RM\", COUNT(DISTINCT \"FROM BRANCH NAME\") AS RM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY \"RM\" ) rm_count ON c.RM = rm_count.RM ); CREATE OR REPLACE TABLE snitch_db_wooqer3 AS ( WITH store_list AS ( SELECT DISTINCT \"coverage-name\" AS Store FROM export_report_2_export_report ), store_mapping AS ( SELECT DISTINCT \"coverage-name\", CASE WHEN \"coverage-name\" = \'NEW BEL ROAD BANGALORE\' THEN \'SNITCH - COCO - BEL ROAD\' WHEN \"coverage-name\" = \'BHARTIYA CITY\' THEN \'SNITCH - COCO - BHARTIYA CITY\' WHEN \"coverage-name\" = \'ESPLANADE MALL\' THEN \'SNITCH - COCO - ESPLANADE MALL\' WHEN \"coverage-name\" = \'HILITE\' THEN \'SNITCH - COCO - HILITE\' WHEN \"coverage-name\" = \'HSR LAYOUT BANGALORE\' THEN \'SNITCH - COCO - HSR LAYOUT\' WHEN \"coverage-name\" = \'JAYANAGAR BANGALORE\' THEN \'SNITCH - COCO - JAYANAGAR\' WHEN \"coverage-name\" = \'MantriAvenue\' THEN \'SNITCH - COCO - KORMANGLA\' WHEN \"coverage-name\" = \'Lulu Mall\' THEN \'SNITCH - COCO - LULU MALL\' WHEN \"coverage-name\" = \'AMANORA\' THEN \'SNITCH - COFO - AMANORA\' WHEN \"coverage-name\" = \'BANER PUNE\' THEN \'SNITCH - COFO - BANER\' WHEN \"coverage-name\" = \'BRIGADE ROAD BANGALORE\' THEN \'SNITCH - COFO - BRIGADE ROAD\' WHEN \"coverage-name\" = \'CITY CENTER\' THEN \'SNITCH - COFO - CC MANGALORE\' WHEN \"coverage-name\" = \'INFINITI ANDHERI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN \"coverage-name\" = \'INFINITI MALAD\' THEN \'SNITCH - COFO - INFINITI MALAD\' WHEN \"coverage-name\" = \'INFINITY VASHI\' THEN \'SNITCH - COFO - INORBIT VASHI\' WHEN \"coverage-name\" = \'KUKATPALLY\' THEN \'SNITCH - COFO - KUKATPALLY\' WHEN \"coverage-name\" = \'BANDRA\' THEN \'SNITCH - COFO - LINKING ROAD\' WHEN \"coverage-name\" = \'Kalyan Metro\' THEN \'SNITCH - COFO - METRO MALL\' WHEN \"coverage-name\" = \'RAJPUR ROAD DEHRADUN\' THEN \'SNITCH - COFO - RAJPURA ROAD\' WHEN \"coverage-name\" = \'SARATH CITY\' THEN \'SNITCH - COFO - SARATH CITY\' WHEN \"coverage-name\" = \'TRIBECA\' THEN \'SNITCH - COFO - TRIBECA\' WHEN \"coverage-name\" = \'VIP ROAD VIZAG\' THEN \'SNITCH - COFO - VIZAG\' WHEN \"coverage-name\" = \'C ROAD JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN \"coverage-name\" = \'DB MALL BHOPAL\' THEN \'SNITCH - FOCO - DB 